import json, hashlib, pathlib, collections
ROOT=pathlib.Path('data/catalog-candidates/catalog-production-001')
OUT=ROOT/'batch-009/research/science'
BASE=json.loads((ROOT/'baseline-index.json').read_text())
ELIG={c['id']:c for c in json.loads((OUT/'eligible-identities.json').read_text())['concepts']}
S=[]; P=[]; ISSUES=[]
STAMP='2026-10-09T04:30:45Z'
def source(sid,title,url,locator,ref,revision=None,mode='web_open_text'):
    S.append(dict(id=sid,title=title,url=url,locator=locator,revision=revision,inspected_at=STAMP,time_basis='UTC checkpoint recorded after actual web inspection; server acquisition timestamp unavailable.',inspection_mode=mode,tool_refs=ref.split(','),word_limit=200,budget_group=url))
def proposal(cid,scope,subfield,takeaway,sid,locator,note,parent=None,limits=None,named=False):
    c=ELIG[cid]; b=BASE['concepts'][cid]; src=next(s for s in S if s['id']==sid)
    assert c['label']==b['label'] and not b.get('card') and not b.get('candidate_records')
    pr=None
    if parent:
        pid,typ,assertion,pnote=parent
        assert pid in BASE['concepts'] and pid!=cid
        pr=dict(target_id=pid,type=typ,assertion=assertion,source_ids=[sid],note=pnote)
    P.append(dict(id=cid,label=c['label'],aliases=c['aliases'],primary_domain=c['domains'][0],primary_subfield=subfield,entity_kind='named_subject' if named else 'idea',scope=scope,learning_takeaway=takeaway,identity_reason='Eligible canonical ID; intended meaning agrees with the frozen source record and the inspected educational treatment.',discovery_evidence=[dict(source_id=sid,url=src['url'],locator=locator,support_note=note,inspection_mode=src['inspection_mode'],tool_refs=src['tool_refs'])],proposed_parent=pr,limits=limits or []))
def write():
    obj=dict(schema_version=1,assignment='science',baseline_index_sha256=hashlib.sha256((ROOT/'baseline-index.json').read_bytes()).hexdigest(),proposals=P,issues=ISSUES,sources_inspected=S)
    (OUT/'proposals.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    (OUT/'sources-inspected.json').write_text(json.dumps(dict(schema_version=1,assignment='science',status='selection_ready_awaiting_reservations' if len(P)==70 else 'selection_in_progress',time_basis='Actual session web inspections, recorded in UTC checkpoints.',sources=S,access_failures=ISSUES),ensure_ascii=False,indent=2)+'\n')
    budgets=[]
    for s in S:
        rows=[p for p in P if any(e['source_id']==s['id'] for e in p['discovery_evidence']) or (p['proposed_parent'] and s['id'] in p['proposed_parent']['source_ids'])]
        texts=[]
        for p in rows:
            texts += [p['learning_takeaway']] + p['limits'] + [e['support_note'] for e in p['discovery_evidence'] if e['source_id']==s['id']]
            if p['proposed_parent'] and s['id'] in p['proposed_parent']['source_ids']:
                texts.append(p['proposed_parent']['note'])
        total=sum(len(t.split()) for t in texts)
        assert total<=s['word_limit']
        budgets.append(dict(source_id=s['id'],url=s['url'],word_limit=s['word_limit'],total_derived_words=total,card_ids=[p['id'] for p in rows],counting_basis='Selection stage: whitespace-separated learning takeaways, support notes, relation notes and limits, each counted once. No card bodies yet. Repeated identical JSON representations are not additional prose. Source titles, locators, inventory names and administrative metadata excluded. Recount with actual card bodies and any new notes after reservations.'))
    (OUT/'source-word-budgets.json').write_text(json.dumps(dict(schema_version=1,budgets=budgets),ensure_ascii=False,indent=2)+'\n')
