def evidence(cid,sid,locator,note):
    p=next(p for p in P if p['id']==cid); s=next(s for s in S if s['id']==sid)
    p['discovery_evidence'].append(dict(source_id=sid,url=s['url'],locator=locator,support_note=note,inspection_mode=s['inspection_mode'],tool_refs=s['tool_refs']))

def parent(cid,pid,typ,assertion,sids,note):
    assert pid in BASE['concepts'] and pid!=cid
    next(p for p in P if p['id']==cid)['proposed_parent']=dict(target_id=pid,type=typ,assertion=assertion,source_ids=sids,note=note)

